
.statusbar {
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  background-color: var(--c-surface);
  border: 2px solid var(--c-border);
  border-radius: 10px;
  overflow: hidden;
  box-shadow: 0 4px 14px rgba(43, 45, 66, 0.14);
  font-size: 13px;
  transition: border-color 0.3s;

  &.is-race {
    border-color: var(--c-danger);
  }
}

.sb-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 14px;
  background: linear-gradient(135deg, var(--c-primary) 0%, var(--c-primary-dark) 100%);
  color: #fff;
  cursor: pointer;
  user-select: none;

  &:hover {
    filter: brightness(1.05);
  }
}

.sb-title-group {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.sb-name {
  font-weight: 800;
  font-size: 1.02rem;
  white-space: nowrap;
}

.sb-level {
  background: var(--c-gold);
  color: var(--c-ink);
  font-weight: 800;
  font-size: 0.72rem;
  padding: 2px 7px;
  border-radius: 10px;
  font-family: var(--font-num);
}

.sb-badge {
  font-size: 0.68rem;
  padding: 2px 8px;
  border-radius: 10px;
  border: 1.5px solid rgba(255, 255, 255, 0.55);
  &.ok { background: rgba(255, 255, 255, 0.18); }
  &.tired { background: var(--c-warning); color: var(--c-ink); }
  &.injured { background: var(--c-danger); }
  &.low { background: var(--c-gold); color: var(--c-ink); }
}

.sb-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.75rem;
  opacity: 0.95;
  white-space: nowrap;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.sb-phase {
  background: rgba(255, 255, 255, 0.2);
  padding: 2px 8px;
  border-radius: 10px;
  font-weight: 700;
  &.active {
    background: var(--c-danger);
  }
}

.sb-toggle {
  font-size: 0.8rem;
  opacity: 0.8;
}

.sb-summary {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px 14px;
  background: var(--c-surface-alt);
  border-bottom: 2px solid var(--c-border);
}

.bar-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.bar-label {
  width: 78px;
  font-size: 0.78rem;
  color: var(--c-muted);
  white-space: nowrap;
  i { margin-right: 4px; }
}

.bar-track {
  flex: 1;
  height: 11px;
  background: var(--c-track);
  border-radius: 6px;
  overflow: hidden;
  position: relative;
}

.bar-fill {
  height: 100%;
  border-radius: 6px;
  transition: width 0.35s ease;
  &.stamina { background: linear-gradient(90deg, var(--c-primary), #4caf7d); }
  &.spirit { background: linear-gradient(90deg, var(--c-warning), #ffb703); }
  &.bond { background: linear-gradient(90deg, var(--c-stat-speed), var(--c-danger)); }
}

.bar-value {
  width: 52px;
  text-align: right;
  font-family: var(--font-num);
  font-weight: 700;
  font-size: 0.82rem;
  small { color: var(--c-muted); font-weight: 400; }
}

.fan-row {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.8rem;
  color: var(--c-muted);
  strong {
    color: var(--c-gold);
    font-family: var(--font-num);
    font-size: 0.9rem;
  }
}

.sb-body {
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  background: var(--c-surface);
}

.sb-tabs {
  display: flex;
  gap: 6px;
  border-bottom: 2px solid var(--c-border);
  padding-bottom: 8px;
}

.sb-tab {
  flex: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border: 1px solid var(--c-border);
  background: var(--c-surface-alt);
  border-radius: 8px;
  padding: 6px 10px;
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--c-muted);
  cursor: pointer;
  transition: all 0.2s;
  i { font-size: 0.72rem; }
  &:hover { border-color: var(--c-primary); color: var(--c-primary-dark); }
  &.active {
    background: var(--c-primary);
    border-color: var(--c-primary-dark);
    color: #fff;
  }
}

.rel-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.rel-card {
  border: 1px solid var(--c-border);
  border-radius: 10px;
  padding: 10px 12px;
  background: var(--c-surface-alt);
}

.rel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  .rel-name { font-weight: 800; font-size: 0.9rem; color: var(--c-primary-dark); }
  .rel-bond {
    font-family: var(--font-num);
    font-weight: 800;
    font-size: 0.82rem;
    padding: 2px 9px;
    border-radius: 10px;
    &.deep { background: #e6f5ef; color: #1f6e42; }
    &.mid { background: #fdf0dc; color: #b06e1a; }
    &.low { background: #e6f2f8; color: #185fa5; }
    &.cold { background: var(--c-track); color: var(--c-muted); }
  }
}

.rel-bar {
  margin-top: 6px;
  .bar-value { width: auto; }
}

.rel-skills {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 8px;
}

.rel-skill {
  font-size: 0.7rem;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 8px;
  background: var(--c-surface-alt);
  border: 1px solid var(--c-border);
  color: var(--c-muted);
  em { font-style: normal; font-family: var(--font-num); font-weight: 700; margin-left: 3px; }
  &.high { background: #e6f5ef; border-color: #bfe3d3; color: #1f6e42; }
}

.rel-noskills {
  margin-top: 8px;
  font-size: 0.72rem;
  color: var(--c-muted);
  font-style: italic;
}

.sb-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.sb-section-title {
  font-size: 0.85rem;
  font-weight: 800;
  color: var(--c-primary-dark);
  border-left: 4px solid var(--c-primary);
  padding-left: 8px;
  i { margin-right: 5px; }
}

.stat-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 8px;
}

.stat-cell {
  display: flex;
  align-items: center;
  gap: 8px;
  border: 1px solid var(--c-border);
  border-radius: 8px;
  padding: 6px 9px;
  background: var(--c-surface-alt);
}

.stat-name {
  width: 40px;
  font-size: 0.78rem;
  font-weight: 700;
}

.stat-track {
  flex: 1;
  height: 9px;
  background: var(--c-track);
  border-radius: 5px;
  overflow: hidden;
}

.stat-fill {
  height: 100%;
  border-radius: 5px;
  transition: width 0.35s ease;
  &.速度 { background: linear-gradient(90deg, var(--c-stat-speed), #ef9a8f); }
  &.耐力 { background: linear-gradient(90deg, var(--c-stat-stamina), #7fbfdd); }
  &.力量 { background: linear-gradient(90deg, var(--c-stat-power), #f2c078); }
  &.毅力 { background: linear-gradient(90deg, var(--c-stat-grit), #b3a7d0); }
  &.智慧 { background: linear-gradient(90deg, var(--c-stat-intel), #7ccdb4); }
}

.stat-value {
  width: 42px;
  text-align: right;
  font-family: var(--font-num);
  font-weight: 700;
  font-size: 0.8rem;
}

.stat-total {
  font-size: 0.8rem;
  color: var(--c-muted);
  text-align: right;
  strong { color: var(--c-ink); font-family: var(--font-num); }
  .total-hint { font-size: 0.7rem; }
}

.apt-grid {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.apt-group {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.apt-group-name {
  width: 44px;
  font-size: 0.75rem;
  font-weight: 800;
  color: var(--c-muted);
}

.apt-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  border: 1px solid var(--c-border);
  border-radius: 6px;
  padding: 2px 7px;
  background: var(--c-surface-alt);
  font-size: 0.72rem;
  b { color: var(--c-muted); font-weight: 600; }
  em {
    font-style: normal;
    font-weight: 800;
    font-family: var(--font-num);
    color: var(--c-primary-dark);
  }
}

.skill-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.skill-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.skill-name {
  width: 120px;
  font-size: 0.78rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.skill-track {
  flex: 1;
  height: 9px;
  background: var(--c-track);
  border-radius: 5px;
  overflow: hidden;
}

.skill-fill {
  height: 100%;
  border-radius: 5px;
  background: linear-gradient(90deg, var(--c-muted), #a9b3c2);
  transition: width 0.35s ease;
  &.high { background: linear-gradient(90deg, var(--c-primary), #4caf7d); }
}

.skill-value {
  width: 42px;
  text-align: right;
  font-family: var(--font-num);
  font-weight: 700;
  font-size: 0.78rem;
}

.empty-note {
  font-size: 0.78rem;
  color: var(--c-muted);
  font-style: italic;
  padding: 6px 0;
}

.ach-count {
  font-size: 0.72rem;
  color: var(--c-warning);
  font-weight: 700;
  margin-left: 2px;
}

.ach-list {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.ach-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 1px solid var(--c-border);
  border-radius: 14px;
  padding: 3px 10px;
  background: var(--c-surface-alt);
  font-size: 0.78rem;
  i { color: var(--c-warning); font-size: 0.72rem; }
}

.ach-name {
  font-weight: 700;
  color: var(--c-primary-dark);
}

.ach-year {
  font-size: 0.68rem;
  color: var(--c-muted);
  font-family: var(--font-num);
  border-left: 1px solid var(--c-border);
  padding-left: 6px;
}

.race-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
  border: 1px solid var(--c-border);
  border-radius: 8px;
  padding: 10px;
  background: var(--c-surface-alt);
}

.race-head {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  strong { font-size: 0.95rem; }
}

.race-tag {
  background: var(--c-primary);
  color: #fff;
  font-size: 0.68rem;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 10px;
}

.race-meta {
  font-size: 0.78rem;
  color: var(--c-muted);
}

.stage-row {
  display: flex;
  gap: 8px;
  margin-top: 4px;
}

.stage-chip {
  padding: 3px 10px;
  border-radius: 6px;
  font-family: var(--font-num);
  font-weight: 700;
  font-size: 0.8rem;
  &.pos { background: #e6f5ef; color: var(--c-primary-dark); }
  &.neg { background: #fbe9e4; color: var(--c-danger); }
  &.neu { background: var(--c-track); color: var(--c-muted); }
}

.race-result {
  font-size: 0.8rem;
  strong { color: var(--c-gold); }
}

@media (max-width: 600px) {
  .stat-grid { grid-template-columns: 1fr; }
  .sb-meta { font-size: 0.68rem; }
  .sb-name { font-size: 0.92rem; }
}
